package uk.ac.ravensbourne.casevault.security;
import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.core.io.ClassPathResource; import org.springframework.stereotype.Service;
/** Enforces length and breached/common-password defences without composition-rule theatre (CWE-521). */
@Service public class PasswordPolicy { private final Set<String> common; public PasswordPolicy() {try(var in=new ClassPathResource("security/common-passwords.txt").getInputStream()){common=Set.copyOf(new String(in.readAllBytes(),StandardCharsets.UTF_8).lines().map(String::trim).filter(s->!s.isEmpty()).toList());}catch(IOException e){throw new IllegalStateException("Common password list unavailable",e);}} public void validate(String password,String email){if(password==null||password.length()<12||password.length()>128||common.contains(password.toLowerCase(Locale.ROOT))||password.equalsIgnoreCase(email))throw new IllegalArgumentException("Password does not meet policy");} }
